def runs2(fr,ch,r0,r1,c0,c1):
    row=fr.ascii.split('\n')
    out=[]
    for r in range(r0,r1+1):
        s=row[r][c0:c1+1]; i=0
        while i<len(s):
            if s[i]==ch:
                j=i
                while j+1<len(s) and s[j+1]==ch: j+=1
                out.append((r,c0+i,c0+j)); i=j+1
            else: i+=1
    return out

